"""Render static pages from approved content. Python standard library only."""
from pathlib import Path
import json, html, re
ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'content.json').read_text())
E=DATA['event']; P=sorted([p for p in DATA['problems'] if p.get('published', True)], key=lambda p:int(re.search(r'\d+',p['id']).group())); J=DATA['judges']
assert len({p['slug'] for p in P}) == len(P), 'Duplicate problem slugs'
assert len({p['id'] for p in P}) == len(P), 'Duplicate problem numbers'
esc=html.escape
REG=E['registrationUrl'] or '/#registration'
DEADLINE_DATE,_,DEADLINE_TIME=E['deadline'].partition(', ')
SCHEDULE=DATA['evaluationSchedule'];NOTICES=DATA['announcements']

def header(directory=False):
 return f'''<header class="site-header"><a class="brand" href="/" aria-label="ACE Club home"><img src="/assets/ace.jpeg" alt="ACE Club" width="52" height="52"><span>{esc(E["name"])}<small>ACE CLUB · RAMAIAH INSTITUTE OF TECHNOLOGY</small></span></a><nav aria-label="Main navigation"><a href="/problem-statements/" {'aria-current="page"' if directory else ''}>Problem Statements</a><a href="/#judges">Judges</a><a href="/#faq">FAQ</a><a class="nav-schedule" href="/#evaluation-schedule">Schedule</a><a class="nav-register" href="{REG}" data-register>Register Now <span aria-hidden="true">↗</span></a></nav></header>'''

def footer():return f'''<footer class="site-footer"><a class="wordmark" href="/">{esc(E["name"])}<span aria-hidden="true">↗</span></a><p>Organized by ACE Club<br>Ramaiah Institute of Technology</p><div class="footer-links"><a href="/credits.html">Visual credits</a><a href="#top">Back to top ↑</a></div></footer>'''

gallery_script='<script src="/gallery.js" defer></script>'

def page(title,body,directory=False,detail=False,animated=False):
 hero_font='<link rel="preload" href="/assets/josefin-sans-latin-400.woff2" as="font" type="font/woff2" crossorigin>' if not directory else ''
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#05080e"><meta name="description" content="{esc(E["name"])} by ACE Club, Ramaiah Institute of Technology. 13 November 2026, {esc(E["venue"])}. Code. Create. Conquer."><title>{esc(title)} · {esc(E["name"])}</title><link rel="icon" href="/assets/ace.jpeg">{hero_font}<link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script><script type="module" src="/scene.js"></script>{gallery_script if not directory else ''}</head><body id="top" class="{'directory' if directory else 'home'} {'detail-page' if detail else ''}{' cosmic-directory' if animated else ''}"><a class="skip-link" href="#main">Skip to content</a><div class="universe" aria-hidden="true"><canvas id="universe-canvas"></canvas><div class="scene-fallback"></div><div class="scene-shade"></div></div>{header(directory)}{body}{footer()}<a class="floating-register" href="{REG}" data-register hidden>Register Now <span aria-hidden="true">↗</span></a><div class="sr-only" id="announcement" role="status"></div></body></html>'''

def picture(name,alt,cls='',url=None):
 content=f'<div class="logo-safe"><img src="/assets/{name}" alt="{esc(alt)}" loading="lazy"></div><span>{esc(alt)}</span>'
 if url:return f'<a class="logo-card {cls}" href="{esc(url,quote=True)}" target="_blank" rel="noopener noreferrer" aria-label="{esc(alt)} — opens in a new tab">{content}</a>'
 return f'<div class="logo-card {cls}">{content}</div>'

def subtitle(p,cls='problem-subtitle'):
 return f'<p class="{cls}">{esc(p["subtitle"])}</p>' if p.get('subtitle') else ''

def brief_html(p):
 if p.get('format')=='statement':return f'<section class="brief-section"><h2>Problem Statement</h2><p>{esc(p["description"])}</p></section>'
 return f'<section class="brief-section"><h2>Problem Description</h2><p>{esc(p["description"])}</p></section><section class="brief-section"><h2>Your Challenge</h2><p>{esc(p["challenge"])}</p></section>'

sponsors=''.join(picture(s['image'],s['name'],'sponsor '+s['className'],s['url']) for s in DATA['sponsors'])
gallery_items=''.join(f'<a class="gallery-item" href="{esc(image["src"])}" data-gallery-index="{i}" aria-label="Open photograph {i+1} of {len(DATA["gallery"])}"><img src="{esc(image["thumbnail"])}" srcset="{esc(image["thumbnail"])} {image["thumbWidth"]}w, {esc(image["src"])} {image["width"]}w" sizes="(max-width: 600px) 90vw, (max-width: 1000px) 44vw, 65vw" width="{image["width"]}" height="{image["height"]}" alt="{esc(image["alt"])}" loading="lazy" decoding="async"><span class="gallery-zoom" aria-hidden="true">↗</span></a>' for i,image in enumerate(DATA['gallery']))
gallery=f'''<section class="section gallery" id="gallery" aria-labelledby="gallery-title"><div class="gallery-heading reading-surface"><p class="eyebrow">ACE CLUB / IN PICTURES</p><h2 id="gallery-title">A glimpse into what we have accomplished together.</h2></div><div class="gallery-grid">{gallery_items}</div></section><dialog class="gallery-lightbox" aria-labelledby="gallery-viewer-title"><h2 class="sr-only" id="gallery-viewer-title">Photograph viewer</h2><div class="lightbox-toolbar"><p class="lightbox-count" aria-live="polite"></p><button type="button" class="lightbox-close" aria-label="Close photograph viewer">Close <span aria-hidden="true">×</span></button></div><figure class="lightbox-figure"><img class="lightbox-image" alt=""><p class="lightbox-error" role="status" hidden>Unable to load this photograph.</p></figure><div class="lightbox-controls"><button type="button" class="lightbox-prev" aria-label="Previous photograph">←</button><span aria-hidden="true">← / →</span><button type="button" class="lightbox-next" aria-label="Next photograph">→</button></div></dialog>'''

judges=''
for i,j in enumerate(J,1):
 number=f'{i:02d}'
 logo_path=DATA['organizationLogos'].get(j.get('organization'))
 logo=f'<div class="judge-logo company-logo"><img src="{esc(logo_path)}" alt="{esc(j["organization"])} logo" loading="lazy" decoding="async"></div>' if logo_path else ''
 profile=f'<a class="profile-link" href="{esc(j["linkedin"])}" target="_blank" rel="noopener noreferrer"><span class="linkedin-icon" aria-hidden="true">in</span> LinkedIn <span aria-hidden="true">↗</span><span class="sr-only"> — {esc(j["name"])}, opens in a new tab</span></a>' if j.get('linkedin') else ''
 judges+=f'<article class="judge-card" aria-labelledby="judge-{number}-name">{logo}<div class="judge-body"><p class="eyebrow">JUDGE {number}</p><h3 id="judge-{number}-name">{esc(j["name"])}</h3><p class="judge-company">{esc(j.get("organization") or "Affiliation to be announced")}</p><p class="judge-education">{esc(j.get("education") or "")}</p>{profile}</div></article>'
providers=''.join(f'<div class="provider-name"><span>{i:02d}</span><strong>{esc(name)}</strong></div>' for i,name in enumerate(DATA['problemProviders'],1))
preview=''.join(f'<a class="preview-row" href="/problem-statements/{p["slug"]}/"><span class="problem-index">{p["id"]}</span><h3>{esc(p["title"])}</h3><span class="row-arrow" aria-hidden="true">↗</span></a>' for p in P[:3])

def schedule_facts(record):
 rows=[('Date',f'<time datetime="{esc(record["isoDate"])}">{esc(record["date"])}</time>'),('Time',esc(record['time'])),('Mode',esc(record['mode']))]
 if record.get('venue'):rows.append(('Venue',esc(record['venue'])))
 if record.get('evaluators'):rows.append(('Evaluators',esc(record['evaluators'])))
 return '<dl class="schedule-details">'+''.join(f'<div><dt>{label}</dt><dd>{value}</dd></div>' for label,value in rows)+'</dl>'

semester_cards=''.join(f'<article class="evaluation-card reading-surface" aria-labelledby="semester-{i}"><div class="evaluation-card-heading"><h3 id="semester-{i}">{esc(item["semesters"])}</h3><span class="mode-badge mode-{item["mode"].lower()}">{esc(item["mode"])}</span></div>{schedule_facts(item)}</article>' for i,item in enumerate(SCHEDULE['firstRound'],1))
final=SCHEDULE['finalRound']
event_information=f'''<section class="section event-information" id="event-flow" aria-labelledby="evaluation-schedule"><div class="section-introduction reading-surface"><p class="eyebrow">EVENT INFORMATION / ROUND 01</p><h2 id="evaluation-schedule">Evaluation Schedule</h2><p class="intro">First-round evaluations for your semester. Find your date, time and mode below.</p></div><div class="evaluation-grid">{semester_cards}</div><aside class="information-notice reading-surface" aria-labelledby="prototype-title"><p class="eyebrow">BUILD YOUR PROTOTYPE</p><h3 id="prototype-title">Prototype Development Instructions</h3><p>{esc(NOTICES['prototype'])}</p></aside><article class="final-round reading-surface" id="final-round" aria-labelledby="final-title"><p class="eyebrow">ROUND 02 / SHORTLISTED TEAMS</p><h3 id="final-title">{esc(final['title'])}</h3><p class="eligibility-notice"><strong>{esc(final['announcement'])}</strong></p><p class="qualification-note">{esc(final['qualification'])}</p>{schedule_facts(final)}<p class="final-eligibility"><strong>Eligibility:</strong> {esc(final['eligibility'])}</p></article><aside class="information-notice reading-surface" aria-labelledby="communication-title"><h3 id="communication-title">Official Updates &amp; Communication</h3><p>{esc(NOTICES['communication'])}</p></aside><article class="rules-panel reading-surface" id="rules" aria-labelledby="rules-title"><h3 id="rules-title">Rules and Regulations</h3><div class="deadline-callout"><p class="eyebrow">REGISTRATIONS CLOSE</p><p class="deadline-date"><time datetime="2026-11-11">{esc(DEADLINE_DATE)}</time> <span>{esc(DEADLINE_TIME)}</span></p><p>{esc(NOTICES['registrationDeadline'])}</p></div><dl class="rules-details"><div><dt>Eligibility</dt><dd>{esc(E['eligibility'])}</dd></div><div><dt>Team size</dt><dd>{esc(E['teamSize'])} members per team</dd></div></dl></article></section>'''
event_shortcut='<div class="event-shortcut container"><a href="#evaluation-schedule"><strong>Evaluation Schedule</strong><span>Find your semester’s date, time and mode <span aria-hidden="true">↓</span></span></a></div>'

body=f'''<main id="main"><section class="hero" id="hero"><div class="hero-content"><p class="eyebrow hero-eyebrow">ACE CLUB PRESENTS <span>·</span> 13 NOVEMBER 2026</p><h1><span class="title-hackstellar">{esc(E["name"].upper())}</span></h1><div class="hero-conversion"><p class="tagline">Code. Create. Conquer.</p><div class="hero-prize"><span class="eyebrow">PRIZE POOL</span><strong>{E['prize']}</strong><span class="prize-note">(with exciting gifts, vouchers and cash prizes)</span></div><div class="hero-actions"><a class="button primary" id="hero-register" href="{REG}" data-register>Register Now <span aria-hidden="true">↗</span></a><a class="hero-secondary" href="/problem-statements/">Explore the challenges <span aria-hidden="true">→</span></a></div><p class="registration-note">{'Registration link coming soon' if not E['registrationUrl'] else ''}</p><p class="hero-meta"><span>13 NOV · 10:00 AM IST</span><span>{esc(E["venue"].upper())}</span></p></div></div><div class="hero-bottom"><a href="#affiliations" class="scroll-cue">EXPLORE THE EVENT <span aria-hidden="true">↓</span></a><button class="mission-detail" id="signal" aria-label="Decode the hidden signal" aria-expanded="false"><span class="signal-dots" aria-hidden="true">· · · ━ ━ ━ · · ·</span><span id="signal-message">SIGNAL / AWAITING CONTACT</span></button></div></section>{event_shortcut}
<section class="section affiliations" id="affiliations"><div class="section-introduction reading-surface"><div class="section-kicker"><span class="eyebrow">01 / A WORLD OF POSSIBILITIES</span><span class="science-note">GRAVITY CONNECTS EVERYTHING</span></div><h2>Ideas without<br>an event horizon.</h2><p class="intro">Professional perspectives. Real-world challenges. Bring your ideas to problems that reach beyond the classroom.</p></div><div class="affiliation-group problem-providers" id="problem-providers"><div class="group-heading"><h3>Problem Statements From</h3><span>Contributed by professionals</span></div><p class="provider-context">Problem statements contributed by professionals from</p><div class="provider-grid">{providers}</div><p class="affiliation-note">Affiliations identify the contributing professionals’ employers, not official company sponsorship or endorsement.</p></div><div class="affiliation-group"><div class="group-heading"><h3>Sponsors</h3><span>With the support of</span></div><div class="sponsor-grid">{sponsors}</div></div></section>
{event_information}
<section class="section challenge-preview" id="challenges"><div class="preview-intro reading-surface"><p class="eyebrow">02 / PICK YOUR PERSPECTIVE</p><h2>Real challenges.<br>Remarkable possibilities.</h2><p class="intro">{len(P):02d} published problem statements. Explore the full briefs in a dedicated space built for focus.</p><a class="button primary" href="/problem-statements/">View Problem Statements <span aria-hidden="true">↗</span></a></div><div class="preview-list">{preview}</div></section>
<section class="section judges" id="judges"><div class="section-introduction reading-surface"><div class="section-kicker"><p class="eyebrow">03 / THE PEOPLE BEHIND THE PERSPECTIVE</p><span class="science-note">DIFFERENT MINDS. SHARED CURIOSITY.</span></div><h2>Meet the Judges</h2></div><div class="judge-grid">{judges}</div></section>
<section class="section faq" id="faq"><div class="faq-introduction reading-surface"><p class="eyebrow">04 / BEFORE YOU BEGIN</p><h2>A few essentials.</h2><p class="intro">The details that matter.</p></div><div class="faq-list"><details><summary>Who can participate?</summary><p>{E['eligibility']}.</p></details><details><summary>How many people can be on a team?</summary><p>Each team must have 2–4 members.</p></details><details><summary>When and where is the event?</summary><p>{esc(E["name"])} starts at 10:00 AM IST on 13 November 2026 at {esc(E["venue"])}, Ramaiah Institute of Technology.</p></details><details><summary>When does registration close?</summary><p>{esc(E["deadline"])}. Registrations will close after this deadline. Use Register Now to open the official Google Form.</p></details></div></section>
<section class="section registration" id="registration"><div class="registration-panel reading-surface"><p class="eyebrow">05 / YOUR NEXT CHALLENGE</p><h2>Great ideas start<br>with a little gravity.</h2><p class="tagline">Code. Create. Conquer.</p><dl class="event-facts"><div><dt>WHEN</dt><dd>{E['date']}<br>{E['start']}</dd></div><div><dt>WHERE</dt><dd>{E['venue']}<br>{E['college']}</dd></div><div><dt>WHO</dt><dd>{E['eligibility']}<br>Teams of {E['teamSize']}</dd></div><div><dt>REGISTRATION DEADLINE</dt><dd>{esc(DEADLINE_DATE)}<br>{esc(DEADLINE_TIME)}</dd></div></dl>{f'<a class="button primary" href="{REG}" data-register>Register Now ↗</a>' if E['registrationUrl'] else '<p class="registration-status">Registration link coming soon</p><p class="muted small">The official Google Form will be linked here once available.</p>'}<button class="cosmic-note" id="time-note" aria-expanded="false">τ ≠ t <span id="time-message">A matter of perspective.</span></button></div></section>{gallery}</main>'''
(ROOT/'index.html').write_text(page('Code. Create. Conquer.',body))

cards=''
for p in P:
 source=p['source'] or 'Contributor to be announced'
 cards+=f'''<article class="problem-card" data-number="{p['id']}" data-domains="{esc('|'.join(p['domains']))}" data-source="{esc(p['source'] or '')}" data-search="{esc((p['id']+' '+p['slug']+' '+p['title']+' '+p['description']+' '+p['challenge']+' '+p['domainLabel']+' '+p.get('subtitle','')).lower(),quote=True)}"><p class="problem-index">{p['id']}</p><h2>{esc(p['title'])}</h2>{subtitle(p)}<div class="domain-tags">{''.join(f'<span>{esc(tag)}</span>' for tag in p['domains'])}</div><p class="problem-summary">{esc(p['summary'])}</p><a class="card-link" href="/problem-statements/{p['slug']}/">View Full Statement <span aria-hidden="true">↗</span></a></article>'''
options=''.join(f'<option>{esc(x)}</option>' for x in list(dict.fromkeys(d for p in P for d in p['domains'])))
sources=[]  # Organizer requested no per-statement company attribution or contributor filtering.
source_filter='<label>Contributor<select id="source"><option value="">All contributors</option>'+''.join(f'<option>{esc(x)}</option>' for x in sources)+'</select></label>' if sources else ''
directory=f'''<main class="directory-main" id="main"><section class="directory-heading container"><a class="back-link" href="/">← Back to Home</a><p class="eyebrow">THE CHALLENGE DIRECTORY</p><div class="directory-title"><h1>PROBLEM<br>STATEMENTS<span>.</span></h1><div class="published-count"><strong>{len(P):02d}</strong><span>Problem Statements Available</span></div></div><p class="directory-subtitle">{len(P)} Challenges. Endless Possibilities.</p><p class="intro">Problem statements contributed by professionals employed at Amazon, TCS, HP, Blackhawk Networks, and Cisco. Contributions are personal, not official corporate submissions.</p><p class="directory-instructions">Search by title, problem number or keyword. Open a statement to read the complete official brief.</p><form class="filter-toolbar" role="search" onsubmit="return false"><label class="search-field"><span class="sr-only">Search problem statements</span><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="search" type="search" placeholder="Search statements" autocomplete="off"></label><label>Domain<select id="domain" autocomplete="off"><option value="" selected>All Domains</option>{options}</select></label>{source_filter}<button class="reset-button" id="reset" type="reset">Reset filters</button></form><noscript><p class="muted">Search needs JavaScript. All briefs remain available below.</p><style>.filter-toolbar{{display:none}}</style></noscript><p id="result-count" role="status">Showing {len(P)} of {len(P)} problem statements</p></section><section class="container problem-grid" aria-label="Published problem statements">{cards}</section><div class="container empty-state" id="empty" hidden><span aria-hidden="true">∅</span><h2>No matching signals.</h2><p>Try another keyword or reset the filters.</p><button class="button secondary" id="empty-reset">Reset filters</button></div><div class="container directory-end"><a class="back-link" href="/">← Back to Home</a><span class="science-note">A QUIETER CORNER OF THE UNIVERSE.</span></div></main>'''
(ROOT/'problem-statements/index.html').write_text(page('Problem Statements',directory,True,animated=True))
for p in P:
 destination=ROOT/'problem-statements'/p['slug'];destination.mkdir(exist_ok=True)
 domains=f'<div class="brief-meta"><p><span>DOMAINS</span>{" / ".join(map(esc,p["domains"]))}</p></div>' if p["domains"] else ""
 body=f'''<main id="main" class="brief-main"><article class="brief-document"><a class="back-link" href="/problem-statements/">← All Problem Statements</a><p class="problem-index">{p['id']}</p><h1>{esc(p['title'])}</h1>{subtitle(p,"brief-subtitle")}{domains}<div class="brief-content">{brief_html(p)}</div><div class="brief-end"><a class="button secondary" href="/problem-statements/">← Back to directory</a><a href="/">Back to Home ↗</a></div></article></main>'''
 (destination/'index.html').write_text(page(p['title'],body,True,True))
print(f'Built homepage, directory and {len(P)} complete brief pages.')

credits = '<main id="main" class="brief-main"><article class="brief-document"><a class="back-link" href="/">← Back to Home</a><h1>Visual credits</h1><div class="brief-content"><h2>Original cosmic environment</h2><p>The black-hole environment is rendered live using a three-dimensional gravitational ray integrator, a procedural accretion disk, perspective stars and orbiting dust. It uses no movie frames, background image or video. The lensing is an artistic real-time approximation, not a scientific measurement or full Kerr simulation.</p><h2>Open-source tools and type</h2><p>Three.js r180, MIT license. Space Grotesk, Inter and Josefin Sans, SIL Open Font License. Local license copies are included with the project.</p><h2>Organizer and sponsor assets</h2><p>ACE Club, PARTEX, Coastal Naati Kitchen and TAGS marks were supplied by the organizer. The Microsoft and Ribbon Communications logos and all eight gallery photographs were also supplied by the organizer. Judge organizations remain separate from sponsors and problem contributors.</p></div></article></main>'
(ROOT/'credits.html').write_text(page('Visual credits', credits, True, True))
